(() => {
  'use strict';

  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const opt = (value, label, selected = false) => `<option value="${esc(value)}" ${selected ? 'selected' : ''}>${esc(label)}</option>`;
  const state = {
    client: null, session: null, member: null, page: 'overview', authMode: 'signin',
    cohortId: null, courseId: null, moduleId: null, assessmentId: null,
    submissionId: null, sessionId: null, participantId: null, generatedCode: null
  };

  const navigation = {
    admin: [['overview', 'Programme overview', 'overview'], ['people', 'People & access', 'people'], ['learning', 'Courses & modules', 'learning'], ['grading', 'Assignments', 'grading'], ['attendance', 'Live attendance', 'attendance'], ['reports', 'Reports', 'reports']],
    mentor: [['overview', 'Mentor overview', 'overview'], ['people', 'My mentees', 'people'], ['grading', 'Assignments', 'grading'], ['attendance', 'Live attendance', 'attendance'], ['reports', 'Reports', 'reports']],
    stakeholder: [['overview', 'Programme overview', 'overview'], ['reports', 'Reports', 'reports']],
    participant: [['learning', 'My learning', 'learning'], ['business', 'My business', 'business']]
  };
  const typeLabels = { video: 'Video', reading: 'Reading', workbook: 'Workbook', multiple_choice: 'Multiple choice', checkboxes: 'Checkboxes', short_text: 'Short answer', long_text: 'Long answer', file_url: 'Assignment link' };

  function icon(name) {
    const paths = {
      overview: '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
      people: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 1 3-3.87"/>',
      learning: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
      attendance: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18M8 15l2 2 5-5"/>',
      reports: '<path d="M3 3v18h18"/><path d="M7 16l4-4 3 3 5-7"/>',
      grading: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',
      business: '<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',
      plus: '<path d="M12 5v14M5 12h14"/>', video: '<polygon points="5 3 19 12 5 21 5 3"/>',
      reading: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V2H6.5A2.5 2.5 0 0 0 4 4.5z"/>',
      workbook: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',
      test: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>'
    };
    return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.overview}</svg>`;
  }

  function toast(message) { const el = $('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 3500); }
  function initials(name) { return String(name || 'TC').split(/\s+/).filter(Boolean).slice(0, 2).map(v => v[0]).join('').toUpperCase(); }
  function dateLabel(value) { if (!value) return 'No expiry'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString('en-MY', { day: 'numeric', month: 'short', year: 'numeric' }); }
  function head(title, description, eyebrow = 'PORTAL', actions = '') { return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions ? `<div class="actions">${actions}</div>` : ''}</div>`; }
  function empty(title, description, iconName = 'overview') { return `<div class="empty-product">${icon(iconName)}<h2>${esc(title)}</h2><p>${esc(description)}</p></div>`; }
  function stat(label, value, note) { return `<div class="stat"><span class="label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`; }
  function modal(id, title, description, body, submit = 'Save') { return `<dialog id="${id}"><form id="${id}-form"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><button class="close-btn" type="button" data-close-dialog aria-label="Close">×</button></div><div class="modal-body">${body}<div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="secondary" type="button" data-close-dialog>Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></div></form></dialog>`; }
  function setFormError(form, message = '') { const box = form?.querySelector('.form-error'); if (!box) return false; box.textContent = message; box.hidden = !message; if (message) box.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); return true; }
  async function rows(table, columns = '*', configure = q => q) { const { data, error } = await configure(state.client.from(table).select(columns)); if (error) throw error; return data || []; }
  async function count(table, configure = q => q) { const { count: total, error } = await configure(state.client.from(table).select('*', { count: 'exact', head: true })); if (error) throw error; return total || 0; }
  async function save(operation, message) { const { error } = await operation; if (error) throw error; toast(message); }

  function renderLogin(message = '', type = '') {
    $('sidebar').hidden = true; document.querySelector('.shell').style.marginLeft = '0'; $('account-control').hidden = true;
    const signin = state.authMode === 'signin';
    $('content').innerHTML = `<div class="auth-layout"><section class="auth-card auth-wide"><div class="eyebrow">LEARNING & IMPACT PORTAL</div><h1>${signin ? 'Welcome back' : 'Join your cohort'}</h1><p>${signin ? 'Sign in to continue to your role-based workspace.' : 'Create a participant account using the private code supplied by your programme team.'}</p><div class="auth-tabs"><button type="button" data-auth-mode="signin" class="${signin ? 'active' : ''}">Sign in</button><button type="button" data-auth-mode="signup" class="${!signin ? 'active' : ''}">Create participant account</button></div>${signin ? `<form id="password-login"><label class="field">Email<input type="email" name="email" autocomplete="email" required></label><label class="field">Password<input type="password" name="password" autocomplete="current-password" required minlength="8"></label><button class="primary" type="submit">Sign in</button></form><details class="magic-details"><summary>Use a magic link instead</summary><form id="magic-login"><label class="field">Email<input type="email" name="email" required></label><button class="secondary" type="submit">Send magic link</button></form></details>` : `<form id="participant-signup"><div class="form-grid"><label class="field full">Cohort signup code<input name="signup_code" required autocomplete="off" placeholder="EKU-XXXXXXXXXXXX" style="text-transform:uppercase"><small>This determines which cohort you join.</small></label><label class="field full">Full name<input name="display_name" required minlength="2" autocomplete="name"></label><label class="field">Email<input type="email" name="email" required autocomplete="email"></label><label class="field">Business name<input name="business_name" autocomplete="organization"></label><label class="field">State<input name="state"></label><span></span><label class="field">Password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label class="field">Confirm password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label></div><button class="primary" type="submit">Create account</button></form>`}<div id="login-message" class="login-message ${esc(type)}" role="alert">${esc(message)}</div></section></div>`;
  }

  function renderNoAccess() {
    $('sidebar').hidden = true; document.querySelector('.shell').style.marginLeft = '0'; $('account-control').hidden = false;
    const email = state.session?.user?.email || ''; $('account-name').textContent = email; $('account-avatar').textContent = initials(email);
    $('content').innerHTML = `<section class="card access-card"><div class="eyebrow">ACCESS PENDING</div><h1>Your account is not assigned to this portal</h1><p>If you are a participant, sign out and create an account using your cohort code. Staff access must be activated by an administrator.</p><div class="actions" style="justify-content:center"><button class="secondary" id="retry-access">Check access again</button><button class="secondary" id="pending-signout">Sign out</button></div></section>`;
  }

  function resetDetails() { state.cohortId = null; state.courseId = null; state.moduleId = null; state.assessmentId = null; state.submissionId = null; state.sessionId = null; state.generatedCode = null; }
  function renderShell() {
    const nav = navigation[state.member.role] || [];
    if (state.page !== 'account' && !nav.some(v => v[0] === state.page)) state.page = nav[0]?.[0] || 'overview';
    $('sidebar').hidden = false; document.querySelector('.shell').style.marginLeft = ''; $('account-control').hidden = false;
    $('account-name').textContent = state.member.display_name; $('account-avatar').textContent = initials(state.member.display_name);
    $('nav').innerHTML = nav.map(([id, label, ico]) => `<button data-page="${id}" class="${state.page === id ? 'active' : ''}">${icon(ico)}${esc(label)}</button>`).join('');
    $('crumb').textContent = state.page === 'account' ? 'Account' : nav.find(v => v[0] === state.page)?.[1] || 'Portal';
  }
  function bars(items, key) { const map = new Map(); items.forEach(item => { const value = item[key] || 'Not provided'; map.set(value, (map.get(value) || 0) + 1); }); const max = Math.max(1, ...map.values()); return [...map].sort((a, b) => b[1] - a[1]).slice(0, 8).map(([label, value]) => `<div class="bar-row"><div class="bar-meta"><span>${esc(label)}</span><b>${value}</b></div><div class="progress"><i style="width:${Math.round(value / max * 100)}%"></i></div></div>`).join(''); }

  async function overview() {
    const [participants, courseCount, modules, classes, checkins, assignments, assessments, submissions] = await Promise.all([
      rows('m_participants', 'id,state,gender'), count('m_courses', q => q.eq('active', true)), count('m_modules', q => q.eq('published', true)), count('m_attendance_sessions', q => q.eq('finalized', true)), rows('m_business_checkins', 'participant_id,sales,operating_costs'), rows('m_module_assignments', 'participant_id,module_id'), rows('m_assessments', 'id,module_id,published'), rows('m_assessment_submissions', 'participant_id,assessment_id,status,passed')
    ]);
    const assessmentModule = new Map(assessments.map(v => [v.id, v.module_id]));
    const passed = new Set(submissions.filter(v => v.passed).map(v => `${v.participant_id}:${assessmentModule.get(v.assessment_id)}`));
    const completion = assignments.length ? Math.round(assignments.filter(v => passed.has(`${v.participant_id}:${v.module_id}`)).length / assignments.length * 100) : 0;
    const income = checkins.length ? Math.round(checkins.reduce((sum, v) => sum + Number(v.sales || 0) - Number(v.operating_costs || 0), 0) / checkins.length) : 0;
    return `${head(state.member.role === 'mentor' ? 'Mentor overview' : 'Programme overview', 'Current participation, learning completion and outcomes within your authorised scope.', `${state.member.role.toUpperCase()} WORKSPACE`)}<div class="stats">${stat('Participants', participants.length, 'Visible active profiles')}${stat('Active courses', courseCount, `${modules} published modules`)}${stat('Module completion', `${completion}%`, `${assignments.length} assigned modules`)}${stat('Average participant income', `RM ${income.toLocaleString('en-MY')}`, 'Average monthly net income submitted')}</div><div class="grid-equal"><section class="card"><div class="card-head"><div><h2>Participants by state</h2><p>Based on participant profiles</p></div></div>${participants.length ? bars(participants, 'state') : empty('No participant profiles', 'State analytics will appear after enrolment.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Participants by gender</h2><p>Only supplied values are counted</p></div></div>${participants.length ? bars(participants, 'gender') : empty('No demographic data', 'Gender analytics will appear after enrolment.', 'people')}</section></div><section class="card"><div class="funnel"><div><span>Finalized classes</span><strong>${classes}</strong></div><div><span>Business submissions</span><strong>${checkins.length}</strong></div><div><span>Learning assignments</span><strong>${assignments.length}</strong></div><div><span>Passed modules</span><strong>${passed.size}</strong></div></div></section>`;
  }

  function membershipTable(members) {
    const staff = members.filter(v => v.role !== 'participant');
    return `<div class="table-wrap"><table><thead><tr><th>Staff account</th><th>Role</th><th>Active</th><th></th></tr></thead><tbody>${staff.map(v => `<tr data-membership="${v.user_id}"><td><strong>${esc(v.display_name)}</strong></td><td><select class="inline-select" data-role>${['admin', 'mentor', 'stakeholder'].map(role => opt(role, role, role === v.role)).join('')}</select></td><td><input data-active type="checkbox" ${v.active ? 'checked' : ''}></td><td><button class="secondary btn-sm" data-save-member>Save</button></td></tr>`).join('')}</tbody></table></div>`;
  }
  function participantTable(participants, mentors, editable) {
    const mentorMap = new Map(mentors.map(v => [v.user_id, v.display_name]));
    return `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Business</th><th>State</th><th>Mentor</th>${editable ? '<th></th>' : ''}</tr></thead><tbody>${participants.map(v => `<tr data-participant="${v.id}"><td><strong>${esc(v.full_name)}</strong><small>${esc(v.email || '—')}</small></td><td>${esc(v.business_name || '—')}</td><td>${esc(v.state || '—')}</td><td>${editable ? `<select class="inline-select" data-mentor><option value="">Unassigned</option>${mentors.map(m => opt(m.user_id, m.display_name, m.user_id === v.mentor_user_id)).join('')}</select>` : esc(mentorMap.get(v.mentor_user_id) || 'Assigned to you')}</td>${editable ? '<td><button class="secondary btn-sm" data-save-mentor>Save</button></td>' : ''}</tr>`).join('')}</tbody></table></div>`;
  }
  function programmeAndCohortModals(programmes) {
    const programmeForm = `<div class="form-grid"><label class="field full">Programme name<input name="name" required></label><label class="field full">Description<textarea name="description"></textarea></label></div>`;
    const cohortForm = `<div class="form-grid"><label class="field">Programme<select name="programme_id" required><option value="">Select programme</option>${programmes.map(v => opt(v.id, v.name)).join('')}</select></label><label class="field">Cohort name<input name="name" required></label><label class="field">State<input name="state"></label><label class="field">Start date<input type="date" name="starts_on"></label><label class="field">End date<input type="date" name="ends_on"></label></div>`;
    return `${modal('programme-modal', 'New programme', 'Create the programme that will contain one or more cohorts.', programmeForm, 'Create programme')}${modal('cohort-modal', 'New cohort', 'Create a participant cohort and then generate its signup code.', cohortForm, 'Create cohort')}`;
  }

  async function people() {
    const participants = await rows('m_participants', 'id,user_id,cohort_id,mentor_user_id,full_name,business_name,email,state,active', q => q.order('full_name'));
    if (state.member.role !== 'admin') return `${head('My mentees', 'Participants assigned to you by an administrator.', 'MENTOR WORKSPACE')}<section class="card">${participants.length ? participantTable(participants, [], false) : empty('No mentees assigned', 'An administrator can assign participants to you.', 'people')}</section>`;
    if (state.cohortId) return cohortWorkspace();
    const [members, cohorts, programmes, codes] = await Promise.all([rows('m_memberships', 'user_id,display_name,role,active', q => q.order('display_name')), rows('m_cohorts', 'id,programme_id,name,state,starts_on,ends_on,active', q => q.order('name')), rows('m_programmes', 'id,name,active', q => q.order('name')), rows('m_signup_codes', 'id,cohort_id,code_hint,expires_at,max_uses,used_count,active')]);
    const programmeMap = new Map(programmes.map(v => [v.id, v.name]));
    const mentorMap = new Map(members.filter(v => v.role === 'mentor').map(v => [v.user_id, v.display_name]));
    const actions = `<button class="secondary" data-open="programme-modal">New programme</button><button class="primary" data-open="cohort-modal">${icon('plus')} New cohort</button>`;
    const cohortCards = cohorts.map(cohort => { const people = participants.filter(v => v.cohort_id === cohort.id); const mentors = [...new Set(people.map(v => v.mentor_user_id).filter(Boolean))]; const activeCodes = codes.filter(v => v.cohort_id === cohort.id && v.active && (!v.expires_at || new Date(v.expires_at) > new Date()) && (v.max_uses == null || v.used_count < v.max_uses)).length; return `<button class="cohort-card" data-open-cohort="${cohort.id}"><div><span class="pill">${esc(programmeMap.get(cohort.programme_id) || 'Programme')}</span><h2>${esc(cohort.name)}</h2><p>${esc(cohort.state || 'All locations')}</p></div><div class="cohort-metrics"><span><strong>${people.length}</strong> participants</span><span><strong>${mentors.length}</strong> mentors</span><span><strong>${activeCodes}</strong> active codes</span></div><small>${mentors.length ? mentors.map(id => mentorMap.get(id)).filter(Boolean).join(', ') : 'No mentor assigned yet'}</small></button>`; }).join('');
    return `${head('People & access', 'Manage enrolment by cohort, mentor responsibility and staff access.', 'ADMINISTRATION', actions)}<section class="card section-gap"><div class="card-head"><div><h2>Cohorts</h2><p>Open a cohort to manage its people, signup codes and course access.</p></div><span class="pill">${cohorts.length} total</span></div>${cohorts.length ? `<div class="cohort-grid">${cohortCards}</div>` : empty('Create your first cohort', 'Start with a programme, then create a cohort for participant signup.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Staff access</h2><p>Existing administrators, mentors and stakeholders</p></div></div>${members.some(v => v.role !== 'participant') ? membershipTable(members) : empty('No staff accounts', 'Staff accounts are provisioned separately from participant signup.', 'people')}</section>${programmeAndCohortModals(programmes)}`;
  }

  async function cohortWorkspace() {
    const [cohorts, programmes, participants, members, codes, access, courses] = await Promise.all([
      rows('m_cohorts', '*', q => q.eq('id', state.cohortId)), rows('m_programmes', 'id,name'), rows('m_participants', 'id,user_id,cohort_id,mentor_user_id,full_name,business_name,email,state,active', q => q.eq('cohort_id', state.cohortId).order('full_name')), rows('m_memberships', 'user_id,display_name,role,active', q => q.order('display_name')), rows('m_signup_codes', 'id,cohort_id,code_hint,expires_at,max_uses,used_count,active,created_at', q => q.eq('cohort_id', state.cohortId).order('created_at', { ascending: false })), rows('m_cohort_access', 'user_id,cohort_id', q => q.eq('cohort_id', state.cohortId)), rows('m_courses', 'id,title,active', q => q.eq('active', true).order('title'))
    ]);
    const cohort = cohorts[0]; if (!cohort) { state.cohortId = null; throw new Error('Cohort not found.'); }
    const programmeMap = new Map(programmes.map(v => [v.id, v.name])); const mentors = members.filter(v => v.role === 'mentor' && v.active); const staff = members.filter(v => ['mentor', 'stakeholder'].includes(v.role) && v.active); const memberMap = new Map(members.map(v => [v.user_id, v])); const assigned = access.map(v => memberMap.get(v.user_id)).filter(Boolean); const assignedMentors = new Set(participants.map(v => v.mentor_user_id).filter(Boolean)); const uncovered = participants.filter(v => !v.mentor_user_id).length;
    const actions = `<button class="secondary" id="back-cohorts">Back to cohorts</button><button class="secondary" data-open="cohort-access-modal">Staff access</button><button class="secondary" data-open="assign-modal">Assign course</button><button class="primary" data-open="signup-code-modal">${icon('plus')} Generate signup code</button>`;
    const codeForm = `<div class="form-grid"><input type="hidden" name="cohort_id" value="${cohort.id}"><label class="field">Expiry date and time<input type="datetime-local" name="valid_until" required></label><label class="field">Maximum signups<input type="number" name="allowed_uses" min="1" value="100" required></label><p class="help-text full">The full code is shown once after generation. Existing codes cannot reveal the original value.</p></div>`;
    const assignForm = `<div class="form-grid"><label class="field">Participant<select name="participant_id" required><option value="">Select participant</option>${participants.map(v => opt(v.id, v.full_name)).join('')}</select></label><label class="field">Course<select name="course_id" required><option value="">Select course</option>${courses.map(v => opt(v.id, v.title)).join('')}</select></label></div>`;
    const accessForm = `<div class="form-grid"><label class="field full">Mentor or stakeholder<select name="user_id" required><option value="">Select staff account</option>${staff.map(v => opt(v.user_id, `${v.display_name} · ${v.role}`)).join('')}</select></label><input type="hidden" name="cohort_id" value="${cohort.id}"></div>`;
    const result = state.generatedCode ? `<dialog id="generated-code-modal"><div class="modal-head"><div><h2>Signup code created</h2><p>Share this code only with the intended participants.</p></div><button class="close-btn" type="button" data-close-dialog>×</button></div><div class="modal-body"><div class="generated-code"><code id="generated-code-value">${esc(state.generatedCode.signup_code)}</code><button class="secondary" id="copy-generated-code">Copy code</button></div><dl class="definition-list"><dt>Cohort</dt><dd>${esc(cohort.name)}</dd><dt>Expires</dt><dd>${esc(dateLabel(state.generatedCode.expires_at))}</dd><dt>Maximum signups</dt><dd>${esc(state.generatedCode.max_uses ?? 'Unlimited')}</dd></dl><div class="form-actions"><button class="primary" type="button" data-close-dialog>Done</button></div></div></dialog>` : '';
    return `${head(cohort.name, `${programmeMap.get(cohort.programme_id) || 'Programme'} · ${cohort.state || 'All locations'}`, 'COHORT WORKSPACE', actions)}<div class="stats compact-stats">${stat('Participants', participants.length, 'Registered in this cohort')}${stat('Assigned mentors', assignedMentors.size, `${uncovered} participants unassigned`)}${stat('Staff with access', assigned.length, assigned.map(v => v.display_name).join(', ') || 'No cohort access')}${stat('Active signup codes', codes.filter(v => v.active).length, 'Codes can expire or reach a limit')}</div><section class="card section-gap"><div class="card-head"><div><h2>Participants and mentor assignment</h2><p>Every participant signup appears here automatically.</p></div></div>${participants.length ? participantTable(participants, mentors, true) : empty('Waiting for participant signups', 'Generate a code and share it with this cohort.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Signup code history</h2><p>Only the last four characters are retained for recognition.</p></div></div>${codes.length ? `<div class="table-wrap"><table><thead><tr><th>Code</th><th>Usage</th><th>Expiry</th><th>Status</th></tr></thead><tbody>${codes.map(v => { const available = v.active && (!v.expires_at || new Date(v.expires_at) > new Date()) && (v.max_uses == null || v.used_count < v.max_uses); return `<tr><td><strong>•••• ${esc(v.code_hint)}</strong></td><td>${v.used_count} / ${v.max_uses ?? '∞'}</td><td>${esc(dateLabel(v.expires_at))}</td><td><span class="pill ${available ? '' : 'gray'}">${available ? 'Available' : 'Closed'}</span></td></tr>`; }).join('')}</tbody></table></div>` : empty('No signup codes yet', 'Generate the first private code for this cohort.', 'people')}</section>${modal('signup-code-modal', 'Generate cohort signup code', `New participants will automatically join ${cohort.name}.`, codeForm, 'Generate code')}${modal('assign-modal', 'Assign a course', 'All current modules in the course will be assigned to the selected participant.', assignForm, 'Assign course')}${modal('cohort-access-modal', 'Grant staff access', 'Give a mentor or stakeholder visibility into this cohort.', accessForm, 'Grant access')}${result}`;
  }

  async function learning() { return state.member.role === 'admin' ? courseAdmin() : participantLearning(); }
  async function courseAdmin() {
    if (state.assessmentId) return assessmentBuilder(); if (state.courseId) return courseWorkspace();
    const [courses, modules, resources, assessments] = await Promise.all([rows('m_courses', '*', q => q.order('created_at', { ascending: false })), rows('m_modules', 'id,course_id,published'), rows('m_module_resources', 'id,module_id'), rows('m_assessments', 'id,module_id,published')]);
    const courseForm = `<div class="form-grid"><label class="field full">Course title<input name="title" required></label><label class="field full">Description<textarea name="description" placeholder="Purpose, audience and expected outcomes"></textarea></label></div>`;
    const cards = courses.map(course => { const courseModules = modules.filter(v => v.course_id === course.id); const moduleIds = new Set(courseModules.map(v => v.id)); return `<button class="project-card" data-open-course="${course.id}"><div class="project-card-top"><span class="pill">Course workspace</span><span class="project-arrow">→</span></div><h2>${esc(course.title)}</h2><p>${esc(course.description || 'No course description yet.')}</p><div class="project-stats"><span><strong>${courseModules.length}</strong> modules</span><span><strong>${resources.filter(v => moduleIds.has(v.module_id)).length}</strong> learning items</span><span><strong>${assessments.filter(v => moduleIds.has(v.module_id)).length}</strong> assessments</span></div><small>Open workspace to manage modules and content</small></button>`; }).join('');
    return `${head('Courses', 'Each course is its own project workspace with modules, learning items and assessments.', 'COURSE MANAGEMENT', `<button class="primary" data-open="course-modal">${icon('plus')} Create course</button>`)}${courses.length ? `<div class="project-grid">${cards}</div>` : `<section class="card">${empty('Create your first course', 'Build a course, add modules, then assign it to participants.', 'learning')}</section>`}${modal('course-modal', 'Create course workspace', 'Give the course a clear name and purpose. Modules are added inside the workspace.', courseForm, 'Create course')}`;
  }
  function resourceItem(resource) { return `<div class="content-row"><span class="content-icon ${resource.kind}">${icon(resource.kind)}</span><div><strong>${esc(resource.title)}</strong><small>${esc(typeLabels[resource.kind] || resource.kind)}${resource.external_url ? ' · External link' : ' · Portal content'}</small></div><span class="pill gray">${resource.required ? 'Required' : 'Optional'}</span></div>`; }

  async function courseWorkspace() {
    const [courseRows, modules, resources, assessments, questions] = await Promise.all([rows('m_courses', '*', q => q.eq('id', state.courseId)), rows('m_modules', '*', q => q.eq('course_id', state.courseId).order('sequence_number')), rows('m_module_resources', '*', q => q.order('sequence_number')), rows('m_assessments', '*', q => q.order('created_at')), rows('m_assessment_questions', 'id,assessment_id')]);
    const course = courseRows[0]; if (!course) { state.courseId = null; throw new Error('Course not found.'); }
    const moduleIds = new Set(modules.map(v => v.id));
    const moduleForm = `<div class="form-grid"><input type="hidden" name="course_id" value="${course.id}"><label class="field">Module order<input type="number" name="sequence_number" min="1" value="${modules.length + 1}" required></label><label class="field">Pass mark (%)<input type="number" name="pass_mark" min="0" max="100" value="70" required></label><label class="field full">Module title<input name="title" required></label><label class="field full">Description<textarea name="description"></textarea></label><label class="field">Initial visibility<select name="published"><option value="false">Draft</option><option value="true">Published</option></select></label></div>`;
    const contentForm = `<input type="hidden" name="module_id"><div class="content-type-picker"><label><input type="radio" name="kind" value="video" checked><span>${icon('video')}<b>Video</b><small>YouTube, Vimeo or hosted link</small></span></label><label><input type="radio" name="kind" value="reading"><span>${icon('reading')}<b>Reading</b><small>Formatted lesson text</small></span></label><label><input type="radio" name="kind" value="workbook"><span>${icon('workbook')}<b>Workbook</b><small>Download or document link</small></span></label></div><div class="form-grid"><label class="field full">Item title<input name="title" required></label><label class="field full" data-content-text hidden>Lesson text<textarea name="content" placeholder="Write the reading or supporting instructions here"></textarea></label><label class="field full" data-content-url>External URL<input type="url" name="external_url" placeholder="https://"></label><label class="field">Order<input type="number" name="sequence_number" min="1" value="1" required></label><label class="field checkbox-field"><input type="checkbox" name="required" value="true" checked> Required item</label></div>`;
    const assessmentForm = `<input type="hidden" name="module_id"><div class="form-grid"><label class="field full">Assessment title<input name="title" required></label><label class="field full">Instructions<textarea name="description"></textarea></label><label class="field">Pass mark (%)<input type="number" name="pass_mark" min="0" max="100" value="70" required></label><label class="field">Grading approach<select name="grading_mode"><option value="automatic">Automatic quiz</option><option value="mentor">Mentor-graded assignment</option><option value="mixed">Mixed assessment</option></select></label><p class="help-text full">Question types determine the final behaviour. Multiple choice and checkboxes are auto-graded; written answers and assignment links go to the assigned mentor.</p></div>`;
    const moduleCards = modules.map(module => { const items = resources.filter(v => v.module_id === module.id); const tests = assessments.filter(v => v.module_id === module.id); return `<section class="module-workspace"><div class="module-workspace-head"><div class="module-title"><span class="module-index">${module.sequence_number}</span><div><div class="module-kicker">MODULE ${module.sequence_number}</div><h2>${esc(module.title)}</h2><p>${esc(module.description || 'No module description.')}</p></div></div><div class="actions"><span class="pill ${module.published ? '' : 'amber'}">${module.published ? 'Published' : 'Draft'}</span><button class="secondary btn-sm" data-toggle-module="${module.id}" data-published="${module.published}">${module.published ? 'Unpublish' : 'Publish'}</button></div></div><div class="module-columns"><div><div class="subhead"><div><h3>Learning content</h3><small>Videos, readings and workbooks</small></div><button class="secondary btn-sm" data-add-content="${module.id}">+ Add item</button></div>${items.length ? `<div class="content-list">${items.map(resourceItem).join('')}</div>` : `<div class="mini-empty">No learning content yet.</div>`}</div><div><div class="subhead"><div><h3>Assessments</h3><small>Automatic tests and mentor grading</small></div><button class="secondary btn-sm" data-new-assessment="${module.id}">+ Create</button></div>${tests.length ? `<div class="assessment-list">${tests.map(test => `<button data-open-assessment="${test.id}"><span class="content-icon test">${icon('test')}</span><span><strong>${esc(test.title)}</strong><small>${esc(test.grading_mode)} · ${questions.filter(v => v.assessment_id === test.id).length} questions</small></span><span class="pill ${test.published ? '' : 'amber'}">${test.published ? 'Published' : 'Draft'}</span></button>`).join('')}</div>` : `<div class="mini-empty">No assessment yet.</div>`}</div></div></section>`; }).join('');
    const actions = `<button class="secondary" id="back-courses">Back to courses</button><button class="primary" data-open="module-modal">${icon('plus')} Add module</button>`;
    return `${head(course.title, course.description || 'Course project workspace', 'COURSE WORKSPACE', actions)}<div class="course-summary"><div><strong>${modules.length}</strong><span>Modules</span></div><div><strong>${resources.filter(v => moduleIds.has(v.module_id)).length}</strong><span>Learning items</span></div><div><strong>${assessments.filter(v => moduleIds.has(v.module_id)).length}</strong><span>Assessments</span></div><div><strong>${modules.filter(v => v.published).length}</strong><span>Published modules</span></div></div>${modules.length ? moduleCards : `<section class="card">${empty('Add the first module', 'Modules organise content and assessments into a clear learning path.', 'learning')}</section>`}${modal('module-modal', 'Add module', `Build the next stage of ${course.title}.`, moduleForm, 'Add module')}${modal('content-modal', 'Add learning item', 'Choose the format first, then add the content participants will use.', contentForm, 'Add learning item')}${modal('assessment-modal', 'Create assessment', 'Create the assessment shell, then add as many questions as needed in its builder.', assessmentForm, 'Open assessment builder')}`;
  }

  async function assessmentBuilder() {
    const [assessmentRows, questions, keys] = await Promise.all([rows('m_assessments', '*', q => q.eq('id', state.assessmentId)), rows('m_assessment_questions', '*', q => q.eq('assessment_id', state.assessmentId).order('sequence_number')), rows('m_assessment_keys', '*')]);
    const assessment = assessmentRows[0]; if (!assessment) { state.assessmentId = null; throw new Error('Assessment not found.'); }
    const keyMap = new Map(keys.map(v => [v.question_id, v]));
    const questionForm = `<div class="form-grid"><label class="field">Question type<select name="question_type" id="question-type"><option value="multiple_choice">Multiple choice</option><option value="checkboxes">Checkboxes</option><option value="short_text">Short answer</option><option value="long_text">Long answer</option><option value="file_url">Assignment / file link</option></select></label><label class="field">Points<input type="number" name="points" min="0.5" step="0.5" value="1" required></label><label class="field full">Question or instruction<textarea name="prompt" required></textarea></label><div class="full" data-auto-question><label class="field">Answer choices, one per line<textarea name="options" placeholder="First choice&#10;Second choice&#10;Third choice"></textarea></label><label class="field">Correct choice number(s)<input name="correct_options" placeholder="1 for multiple choice, or 1,3 for checkboxes"><small>Use the choice numbers in the same order as above.</small></label><label class="field">Answer feedback<textarea name="explanation"></textarea></label></div><label class="field">Order<input type="number" name="sequence_number" min="1" value="${questions.length + 1}" required></label><label class="field checkbox-field"><input type="checkbox" name="required" value="true" checked> Required question</label><p class="help-text full" data-manual-question hidden>This response will be sent to the participant's assigned mentor for grading.</p></div>`;
    const cards = questions.map((question, index) => { const key = keyMap.get(question.id); const answer = key ? (Array.isArray(key.correct_answer) ? key.correct_answer.join(', ') : key.correct_answer) : 'Mentor graded'; return `<article class="question-card"><div class="question-number">${index + 1}</div><div><div class="question-meta"><span class="pill ${key ? 'blue' : 'amber'}">${esc(typeLabels[question.question_type] || question.question_type)}</span><span>${question.points} point${Number(question.points) === 1 ? '' : 's'}</span><span>${question.required ? 'Required' : 'Optional'}</span></div><h3>${esc(question.prompt)}</h3>${question.options ? `<div class="option-preview">${question.options.map((v, i) => `<span>${i + 1}. ${esc(v)}</span>`).join('')}</div>` : ''}<small>Answer: ${esc(answer)}</small></div><button class="danger btn-sm" data-delete-question="${question.id}">Remove</button></article>`; }).join('');
    const actions = `<button class="secondary" id="back-course-workspace">Back to course</button><button class="secondary" id="toggle-assessment" data-published="${assessment.published}">${assessment.published ? 'Unpublish' : 'Publish assessment'}</button><button class="primary" data-open="question-modal">${icon('plus')} Add question</button>`;
    return `${head(assessment.title, assessment.description || 'Build and publish the assessment.', 'ASSESSMENT BUILDER', actions)}<div class="builder-banner"><div><span class="pill ${assessment.published ? '' : 'amber'}">${assessment.published ? 'Published' : 'Draft'}</span><h2>${questions.length} questions · ${questions.reduce((sum, v) => sum + Number(v.points), 0)} total points</h2><p>Pass mark ${assessment.pass_mark}% · ${esc(assessment.grading_mode)} grading</p></div><div class="builder-legend"><span><i class="auto-dot"></i> Automatic</span><span><i class="manual-dot"></i> Mentor review</span></div></div><section class="card"><div class="card-head"><div><h2>Questions</h2><p>Add different response types in any order, similar to a form builder.</p></div></div>${questions.length ? `<div class="question-list">${cards}</div>` : empty('Add the first question', 'Use automatic or mentor-graded response types.', 'grading')}</section>${modal('question-modal', 'Add question', 'Choose how the participant should respond. You can add more questions after saving.', questionForm, 'Add question')}`;
  }

  async function participantLearning() {
    if (!state.participantId) { const profiles = await rows('m_participants', 'id', q => q.eq('user_id', state.session.user.id)); state.participantId = profiles[0]?.id || null; }
    if (state.assessmentId) return participantAssessment(); if (state.moduleId) return participantModule();
    const [assignments, modules, courses, progress] = await Promise.all([rows('m_module_assignments', 'participant_id,module_id', q => q.eq('participant_id', state.participantId)), rows('m_modules', 'id,course_id,title,description,sequence_number,published', q => q.eq('published', true).order('sequence_number')), rows('m_courses', 'id,title,description', q => q.eq('active', true).order('title')), rows('m_resource_progress', 'resource_id', q => q.eq('participant_id', state.participantId))]);
    const assignedIds = new Set(assignments.map(v => v.module_id)); const assignedModules = modules.filter(v => assignedIds.has(v.id));
    if (state.courseId) { const course = courses.find(v => v.id === state.courseId); if (!course) { state.courseId = null; throw new Error('This course is not assigned to your account.'); } const courseModules = assignedModules.filter(v => v.course_id === course.id); return `${head(course.title, course.description || 'Your assigned learning path', 'MY COURSE', '<button class="secondary" id="back-my-courses">Back to my courses</button>')}<div class="grid-3">${courseModules.map((module, index) => `<article class="card module-card"><div class="module-cover ${index % 3 === 1 ? 'navy' : index % 3 === 2 ? 'sand' : ''}">${icon('learning')}<span class="module-number">MODULE ${module.sequence_number}</span></div><div class="module-body"><span class="pill">Assigned</span><h2>${esc(module.title)}</h2><p>${esc(module.description || 'Learning module')}</p><button class="primary" data-open-module="${module.id}">Open module</button></div></article>`).join('')}</div>`; }
    const cards = courses.map(course => { const list = assignedModules.filter(v => v.course_id === course.id); if (!list.length) return ''; return `<button class="project-card participant-course" data-open-course="${course.id}"><div class="project-card-top"><span class="pill">Assigned course</span><span class="project-arrow">→</span></div><h2>${esc(course.title)}</h2><p>${esc(course.description || 'Your learning course')}</p><div class="project-stats"><span><strong>${list.length}</strong> modules</span><span><strong>${progress.length}</strong> items studied</span></div><small>Continue learning</small></button>`; }).join('');
    return `${head('My learning', 'Only courses assigned to your participant account are shown here.', 'PARTICIPANT WORKSPACE')}${assignedModules.length ? `<div class="project-grid">${cards}</div>` : `<section class="card">${empty('No course assigned yet', 'Your programme administrator will assign a course to you.', 'learning')}</section>`}`;
  }

  async function participantModule() {
    const [moduleRows, resources, notes, progress, assessments, submissions] = await Promise.all([rows('m_modules', '*', q => q.eq('id', state.moduleId)), rows('m_module_resources', '*', q => q.eq('module_id', state.moduleId).order('sequence_number')), rows('m_private_notes', '*', q => q.eq('participant_id', state.participantId)), rows('m_resource_progress', 'resource_id', q => q.eq('participant_id', state.participantId)), rows('m_assessments', '*', q => q.eq('module_id', state.moduleId).eq('published', true)), rows('m_assessment_submissions', '*', q => q.eq('participant_id', state.participantId).order('submitted_at', { ascending: false }))]);
    const module = moduleRows[0]; if (!module) throw new Error('Module not found.'); const noteMap = new Map(notes.map(v => [v.resource_id, v.note])); const done = new Set(progress.map(v => v.resource_id));
    const sectionHtml = resources.map(resource => `<section class="card lesson-section"><div class="card-head"><div><span class="pill ${resource.kind === 'video' ? 'blue' : ''}">${esc(typeLabels[resource.kind] || resource.kind)}</span><h2>${esc(resource.title)}</h2></div><span class="pill ${done.has(resource.id) ? '' : 'gray'}">${done.has(resource.id) ? 'Studied' : 'To do'}</span></div>${resource.content ? `<div class="content-block">${esc(resource.content)}</div>` : ''}${resource.external_url ? `<a class="secondary" href="${esc(resource.external_url)}" target="_blank" rel="noopener">Open ${esc(typeLabels[resource.kind] || 'resource')}</a>` : ''}<div class="resource-action"><button class="secondary" data-studied="${resource.id}">${done.has(resource.id) ? 'Mark studied again' : 'Mark as studied'}</button></div><form class="note-form notes" data-resource="${resource.id}"><label class="field">My private notes<textarea name="note" placeholder="Notes are visible only to you">${esc(noteMap.get(resource.id) || '')}</textarea></label><div class="form-error" hidden></div><button class="secondary btn-sm" type="submit">Save notes</button></form></section>`).join('');
    const assessmentHtml = assessments.map(assessment => { const latest = submissions.find(v => v.assessment_id === assessment.id); return `<button class="assessment-entry" data-open-assessment="${assessment.id}"><span class="content-icon test">${icon('test')}</span><span><strong>${esc(assessment.title)}</strong><small>${latest ? (latest.status === 'graded' ? `Latest score ${latest.final_score}%` : 'Submitted for mentor grading') : `${esc(assessment.grading_mode)} · Pass mark ${assessment.pass_mark}%`}</small></span><span class="pill ${latest?.status === 'submitted' ? 'amber' : latest?.passed ? '' : 'gray'}">${latest?.status === 'submitted' ? 'Awaiting review' : latest?.passed ? 'Passed' : 'Open'}</span></button>`; }).join('');
    return `${head(module.title, module.description || 'Assigned learning module', 'MY LEARNING', '<button class="secondary" id="back-modules">Back to course</button>')}<div class="lesson-stack">${sectionHtml || empty('No learning items', 'The administrator is still preparing this module.', 'learning')}${assessments.length ? `<section class="card"><div class="card-head"><div><h2>Assessments</h2><p>Complete automatic tests or submit work for mentor review.</p></div></div><div class="assessment-list participant-list">${assessmentHtml}</div></section>` : ''}</div>`;
  }

  async function participantAssessment() {
    const [assessmentRows, questions, submissions] = await Promise.all([rows('m_assessments', '*', q => q.eq('id', state.assessmentId)), rows('m_assessment_questions', '*', q => q.eq('assessment_id', state.assessmentId).order('sequence_number')), rows('m_assessment_submissions', '*', q => q.eq('assessment_id', state.assessmentId).eq('participant_id', state.participantId).order('submitted_at', { ascending: false }).limit(1))]);
    const assessment = assessmentRows[0]; if (!assessment) throw new Error('Assessment not found.'); const latest = submissions[0];
    const fields = questions.map((question, index) => { let control = ''; if (question.question_type === 'multiple_choice') control = question.options.map(answer => `<label class="answer"><input type="radio" name="q_${question.id}" value="${esc(answer)}" ${question.required ? 'required' : ''}>${esc(answer)}</label>`).join(''); else if (question.question_type === 'checkboxes') control = question.options.map(answer => `<label class="answer"><input type="checkbox" name="q_${question.id}" value="${esc(answer)}">${esc(answer)}</label>`).join(''); else if (question.question_type === 'short_text') control = `<input class="assessment-input" name="q_${question.id}" ${question.required ? 'required' : ''}>`; else if (question.question_type === 'long_text') control = `<textarea class="assessment-input" name="q_${question.id}" ${question.required ? 'required' : ''}></textarea>`; else control = `<input class="assessment-input" type="url" name="q_${question.id}" placeholder="Paste a shareable file or document link" ${question.required ? 'required' : ''}>`; return `<fieldset class="participant-question" data-question-id="${question.id}" data-question-type="${question.question_type}" data-required="${question.required}"><legend><span>${index + 1}</span>${esc(question.prompt)} ${question.required ? '<b>*</b>' : ''}</legend><small>${esc(typeLabels[question.question_type])} · ${question.points} point${Number(question.points) === 1 ? '' : 's'}</small>${control}</fieldset>`; }).join('');
    const previous = latest ? `<div class="submission-status ${latest.status === 'submitted' ? 'pending' : latest.passed ? 'passed' : 'not-passed'}"><strong>${latest.status === 'submitted' ? 'Awaiting mentor grading' : `${latest.final_score}% · ${latest.passed ? 'Passed' : 'Not passed yet'}`}</strong><p>${esc(latest.feedback || (latest.status === 'submitted' ? 'Your assigned mentor has been notified.' : 'You may submit another attempt.'))}</p></div>` : '';
    return `${head(assessment.title, assessment.description || 'Complete every required question before submitting.', 'ASSESSMENT', '<button class="secondary" id="back-assessment-module">Back to module</button>')}${previous}<form id="assessment-submit-form" class="card assessment-form" data-assessment="${assessment.id}">${fields || empty('No questions available', 'This assessment is not ready yet.', 'grading')}<div class="form-error" role="alert" hidden></div>${questions.length ? '<div class="form-actions"><button class="primary" type="submit">Submit assessment</button></div>' : ''}</form>`;
  }

  async function grading() {
    const [submissions, assessments, participants, notifications] = await Promise.all([rows('m_assessment_submissions', '*', q => q.order('submitted_at', { ascending: false })), rows('m_assessments', 'id,title,pass_mark,module_id'), rows('m_participants', 'id,full_name,business_name,mentor_user_id'), rows('m_notifications', '*', q => q.order('created_at', { ascending: false }))]);
    if (state.submissionId) return gradingDetail(submissions, assessments, participants, notifications);
    const assessmentMap = new Map(assessments.map(v => [v.id, v])); const participantMap = new Map(participants.map(v => [v.id, v])); const pending = submissions.filter(v => v.status === 'submitted'); const unread = notifications.filter(v => !v.read_at && v.kind === 'assignment_submitted').length;
    return `${head('Assignments', 'Review participant work that requires mentor judgement. Automatic tests do not enter this queue.', 'GRADING WORKSPACE')}<div class="stats compact-stats">${stat('Awaiting grading', pending.length, 'Manual submissions')}${stat('Unread alerts', unread, 'Assignment notifications')}${stat('Graded submissions', submissions.filter(v => v.status === 'graded').length, 'Visible history')}${stat('Participants', new Set(submissions.map(v => v.participant_id)).size, 'With submissions')}</div><section class="card"><div class="card-head"><div><h2>Submission queue</h2><p>Newest work appears first.</p></div></div>${submissions.length ? `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Assessment</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${submissions.map(v => { const participant = participantMap.get(v.participant_id); const assessment = assessmentMap.get(v.assessment_id); return `<tr><td><strong>${esc(participant?.full_name || 'Participant')}</strong><small>${esc(participant?.business_name || '')}</small></td><td>${esc(assessment?.title || 'Assessment')}</td><td>${esc(dateLabel(v.submitted_at))}</td><td><span class="pill ${v.status === 'submitted' ? 'amber' : v.passed ? '' : 'gray'}">${v.status === 'submitted' ? 'Needs grading' : `${v.final_score}%`}</span></td><td><button class="secondary btn-sm" data-open-submission="${v.id}">${v.status === 'submitted' ? 'Grade' : 'Review'}</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('No submissions yet', 'Mentor-graded work will appear here automatically.', 'grading')}</section>`;
  }

  async function gradingDetail(submissions, assessments, participants, notifications) {
    const submission = submissions.find(v => v.id === state.submissionId); if (!submission) { state.submissionId = null; throw new Error('Submission not found.'); }
    const assessment = assessments.find(v => v.id === submission.assessment_id); const participant = participants.find(v => v.id === submission.participant_id); const questions = await rows('m_assessment_questions', '*', q => q.eq('assessment_id', submission.assessment_id).order('sequence_number'));
    const answerRows = questions.map((question, index) => { const value = submission.answers?.[question.id]; const shown = Array.isArray(value) ? value.join(', ') : value || 'No answer'; return `<article class="review-answer"><span>${index + 1}</span><div><small>${esc(typeLabels[question.question_type])}</small><h3>${esc(question.prompt)}</h3><div>${esc(shown)}</div></div></article>`; }).join('');
    const form = submission.status === 'submitted' ? `<form id="grade-submission-form" class="card grading-panel" data-submission="${submission.id}"><h2>Mentor grade</h2><p>Use a final percentage score across the full assignment.</p><div class="form-grid"><label class="field">Final score (%)<input type="number" name="grade_score" min="0" max="100" step="0.01" required></label><label class="field full">Feedback<textarea name="grade_feedback" required placeholder="Give clear, constructive feedback"></textarea></label></div><div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary" type="submit">Publish grade</button></div></form>` : `<section class="card grading-panel"><span class="pill">Graded</span><h2>${submission.final_score}% · ${submission.passed ? 'Passed' : 'Not passed'}</h2><p>${esc(submission.feedback || 'No feedback provided.')}</p></section>`;
    const related = notifications.filter(v => v.entity_id === submission.id && !v.read_at); if (related.length) state.client.from('m_notifications').update({ read_at: new Date().toISOString() }).in('id', related.map(v => v.id)).then(() => {});
    return `${head(assessment?.title || 'Assignment submission', `${participant?.full_name || 'Participant'} · Submitted ${dateLabel(submission.submitted_at)}`, 'SUBMISSION REVIEW', '<button class="secondary" id="back-grading">Back to queue</button>')}<div class="grading-layout"><section class="card"><div class="card-head"><div><h2>Participant responses</h2><p>Review each answer and any submitted link.</p></div></div><div class="review-list">${answerRows}</div></section>${form}</div>`;
  }

  async function attendance() {
    if (state.sessionId) return register(state.sessionId);
    const [sessions, cohorts] = await Promise.all([rows('m_attendance_sessions', '*', q => q.order('session_date', { ascending: false })), rows('m_cohorts', 'id,name,state', q => q.order('name'))]); const cohortMap = new Map(cohorts.map(v => [v.id, v.name]));
    const body = `<div class="form-grid"><label class="field">Cohort<select name="cohort_id" required><option value="">Select cohort</option>${cohorts.map(v => opt(v.id, v.name)).join('')}</select></label><label class="field">Meeting number<input type="number" name="meeting_number" min="1" required></label><label class="field full">Class title<input name="title" required></label><label class="field">Date<input type="date" name="session_date" required></label><label class="field">Start time<input type="time" name="starts_at"></label><label class="field">Delivery<select name="delivery_mode"><option value="physical">Physical</option><option value="zoom">Zoom</option><option value="teams">Microsoft Teams</option><option value="other">Other</option></select></label><label class="field">Location<input name="location"></label><label class="field full">Meeting link<input type="url" name="join_url" placeholder="https://"></label></div>`;
    const actions = cohorts.length ? `<button class="primary" data-open="session-modal">${icon('plus')} New class register</button>` : '';
    return `${head('Live attendance', 'Record attendance for physical, Zoom or Microsoft Teams classes.', 'ATTENDANCE', actions)}<section class="card">${sessions.length ? `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Cohort</th><th>Session</th><th>Delivery</th><th>Status</th><th></th></tr></thead><tbody>${sessions.map(v => `<tr><td>${esc(v.session_date)}<small>${esc(v.starts_at || '')}</small></td><td>${esc(cohortMap.get(v.cohort_id) || 'Cohort')}</td><td><strong>${esc(v.title)}</strong><small>Meeting ${v.meeting_number}</small></td><td>${esc(v.delivery_mode)}</td><td><span class="pill ${v.finalized ? '' : 'amber'}">${v.finalized ? 'Finalized' : 'Open'}</span></td><td><button class="secondary btn-sm" data-register="${v.id}">Open register</button></td></tr>`).join('')}</tbody></table></div>` : empty('No class registers', 'Create a register when a live class is scheduled.', 'attendance')}</section>${modal('session-modal', 'New class register', 'The session can be physical or hosted externally.', body, 'Create register')}`;
  }
  async function register(id) {
    const sessions = await rows('m_attendance_sessions', '*', q => q.eq('id', id)); const session = sessions[0]; if (!session) throw new Error('Session not found.');
    const [participants, records] = await Promise.all([rows('m_participants', 'id,full_name,business_name', q => q.eq('cohort_id', session.cohort_id).eq('active', true).order('full_name')), rows('m_attendance_records', 'participant_id,status', q => q.eq('session_id', id))]); const map = new Map(records.map(v => [v.participant_id, v.status])); const present = participants.filter(v => map.get(v.id) === 'present').length; const absent = participants.filter(v => map.get(v.id) === 'absent').length;
    const actions = `<button class="secondary" id="back-sessions">Back</button>${session.finalized ? '' : '<button class="primary" id="finalize-session">Finalize register</button>'}`;
    return `${head(session.title, `${session.session_date} · Meeting ${session.meeting_number} · ${session.delivery_mode}`, 'CLASS REGISTER', actions)}<div class="attendance-summary"><div><strong>${present}</strong><span>Present</span></div><div><strong>${absent}</strong><span>Absent</span></div><div><strong>${participants.length - present - absent}</strong><span>Unmarked</span></div></div><section class="card">${participants.length ? `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Business</th><th>Attendance</th></tr></thead><tbody>${participants.map(v => { const status = map.get(v.id) || 'unmarked'; return `<tr><td><strong>${esc(v.full_name)}</strong></td><td>${esc(v.business_name || '—')}</td><td><div class="status-buttons" data-attendee="${v.id}">${['present', 'absent', 'unmarked'].map(s => `<button type="button" data-status="${s}" class="${status === s ? `selected-${s}` : ''}" ${session.finalized ? 'disabled' : ''}>${s}</button>`).join('')}</div></td></tr>`; }).join('')}</tbody></table></div>` : empty('No participants in this cohort', 'Participants who register with the cohort code will appear here.', 'people')}</section>`;
  }

  async function business() { const records = await rows('m_business_checkins', '*', q => q.order('reporting_month', { ascending: false }).limit(24)); return `${head('My business', 'Review monthly business performance.', 'BUSINESS MONITORING')}<section class="card">${records.length ? `<div class="table-wrap"><table><thead><tr><th>Month</th><th>Sales</th><th>Costs</th><th>Net income</th><th>Review</th></tr></thead><tbody>${records.map(v => `<tr><td>${esc(v.reporting_month)}</td><td>RM ${Number(v.sales).toLocaleString('en-MY')}</td><td>RM ${Number(v.operating_costs).toLocaleString('en-MY')}</td><td>RM ${Number(v.sales - v.operating_costs).toLocaleString('en-MY')}</td><td><span class="pill ${v.mentor_reviewed ? '' : 'gray'}">${v.mentor_reviewed ? 'Reviewed' : 'Self-reported'}</span></td></tr>`).join('')}</tbody></table></div>` : empty('No monthly records', 'Your first business check-in will appear here.', 'business')}</section>`; }
  function account() { let ref = 'Configured project'; try { ref = new URL(window.PORTAL_CONFIG.supabaseUrl).hostname.split('.')[0]; } catch {} return `${head('Account', 'Profile and system details are kept here instead of the programme dashboard.', 'ACCOUNT')}<div class="grid-equal"><section class="card"><div class="card-head"><div><h2>Profile</h2><p>Your portal identity</p></div><span class="role-badge">${esc(state.member.role)}</span></div><dl class="definition-list"><dt>Name</dt><dd>${esc(state.member.display_name)}</dd><dt>Email</dt><dd>${esc(state.session.user.email)}</dd><dt>Role</dt><dd>${esc(state.member.role)}</dd><dt>Status</dt><dd>Active</dd></dl></section><section class="card"><div class="card-head"><div><h2>System connection</h2><p>Technical account information</p></div><span class="pill">Connected</span></div><dl class="definition-list"><dt>Database project</dt><dd>${esc(ref)}</dd><dt>Authentication</dt><dd>Supabase Auth</dd><dt>Protection</dt><dd>Row Level Security</dd><dt>Namespace</dt><dd>m_</dd></dl></section></div>`; }
  function reports() { return `${head('Reports', 'Generate stakeholder-ready programme reports from approved records.', 'REPORTING')}<section class="card">${empty('Reports will populate from live records', 'Demographics, completion, attendance, income outcomes and approved stories will be consolidated here.', 'reports')}</section>`; }

  async function loadPage() {
    renderShell(); $('account-menu').hidden = true; $('content').innerHTML = '<div class="loading-card">Loading live data…</div>';
    try { let html; if (state.page === 'overview') html = await overview(); else if (state.page === 'people') html = await people(); else if (state.page === 'learning') html = await learning(); else if (state.page === 'grading') html = await grading(); else if (state.page === 'attendance') html = await attendance(); else if (state.page === 'business') html = await business(); else if (state.page === 'account') html = account(); else html = reports(); $('content').innerHTML = html; if (state.generatedCode && $('generated-code-modal')) $('generated-code-modal').showModal(); }
    catch (error) { console.error(error); $('content').innerHTML = `${head('Database upgrade required', 'One or more product tables or functions are unavailable.', 'ACTION REQUIRED')}<section class="notice amber">${esc(error.message)}</section>${empty('Run the latest database migration', 'Apply 003_cohort_signup_assessments.sql and refresh this page.', 'overview')}`; }
  }
  async function loadMembership() { const { data, error } = await state.client.from('m_memberships').select('user_id,display_name,role,active').eq('user_id', state.session.user.id).eq('active', true).maybeSingle(); if (error) throw error; state.member = data; if (!data) renderNoAccess(); else loadPage(); }

  document.addEventListener('click', async event => {
    try {
      const authMode = event.target.closest('[data-auth-mode]'); if (authMode) { state.authMode = authMode.dataset.authMode; renderLogin(); return; }
      const page = event.target.closest('[data-page]'); if (page && state.member) { state.page = page.dataset.page; resetDetails(); await loadPage(); return; }
      if (event.target.closest('#account-trigger')) { $('account-menu').hidden = !$('account-menu').hidden; return; }
      if (event.target.closest('#sign-out') || event.target.closest('#pending-signout')) { await state.client.auth.signOut(); return; }
      if (event.target.closest('#retry-access')) { await loadMembership(); return; }
      const open = event.target.closest('[data-open]'); if (open) { $(open.dataset.open)?.showModal(); return; }
      const close = event.target.closest('[data-close-dialog]'); if (close) { close.closest('dialog').close(); return; }
      const cohort = event.target.closest('[data-open-cohort]'); if (cohort) { state.cohortId = cohort.dataset.openCohort; await loadPage(); return; }
      if (event.target.closest('#back-cohorts')) { state.cohortId = null; state.generatedCode = null; await loadPage(); return; }
      const course = event.target.closest('[data-open-course]'); if (course) { state.courseId = course.dataset.openCourse; state.moduleId = null; await loadPage(); return; }
      if (event.target.closest('#back-courses')) { state.courseId = null; await loadPage(); return; }
      if (event.target.closest('#back-my-courses')) { state.courseId = null; await loadPage(); return; }
      const content = event.target.closest('[data-add-content]'); if (content) { $('content-modal').querySelector('[name=module_id]').value = content.dataset.addContent; $('content-modal').showModal(); return; }
      const newAssessment = event.target.closest('[data-new-assessment]'); if (newAssessment) { $('assessment-modal').querySelector('[name=module_id]').value = newAssessment.dataset.newAssessment; $('assessment-modal').showModal(); return; }
      const assessment = event.target.closest('[data-open-assessment]'); if (assessment) { state.assessmentId = assessment.dataset.openAssessment; await loadPage(); return; }
      if (event.target.closest('#back-course-workspace')) { state.assessmentId = null; await loadPage(); return; }
      if (event.target.closest('#back-assessment-module')) { state.assessmentId = null; await loadPage(); return; }
      if (event.target.closest('#toggle-assessment')) { const button = event.target.closest('#toggle-assessment'); await save(state.client.from('m_assessments').update({ published: button.dataset.published !== 'true' }).eq('id', state.assessmentId), 'Assessment visibility updated.'); await loadPage(); return; }
      const deleteQuestion = event.target.closest('[data-delete-question]'); if (deleteQuestion) { if (window.confirm('Remove this question and its answer key?')) { await save(state.client.from('m_assessment_questions').delete().eq('id', deleteQuestion.dataset.deleteQuestion), 'Question removed.'); await loadPage(); } return; }
      const toggle = event.target.closest('[data-toggle-module]'); if (toggle) { await save(state.client.from('m_modules').update({ published: toggle.dataset.published !== 'true' }).eq('id', toggle.dataset.toggleModule), 'Module visibility updated.'); await loadPage(); return; }
      const saveMember = event.target.closest('[data-save-member]'); if (saveMember) { const tr = saveMember.closest('[data-membership]'); await save(state.client.from('m_memberships').update({ role: tr.querySelector('[data-role]').value, active: tr.querySelector('[data-active]').checked }).eq('user_id', tr.dataset.membership), 'Staff access updated.'); await loadPage(); return; }
      const saveMentor = event.target.closest('[data-save-mentor]'); if (saveMentor) { const tr = saveMentor.closest('[data-participant]'); await save(state.client.from('m_participants').update({ mentor_user_id: tr.querySelector('[data-mentor]').value || null }).eq('id', tr.dataset.participant), 'Mentor assignment updated.'); await loadPage(); return; }
      const copy = event.target.closest('#copy-generated-code'); if (copy) { await navigator.clipboard.writeText($('generated-code-value').textContent); copy.textContent = 'Copied'; return; }
      const registerButton = event.target.closest('[data-register]'); if (registerButton) { state.sessionId = registerButton.dataset.register; await loadPage(); return; }
      if (event.target.closest('#back-sessions')) { state.sessionId = null; await loadPage(); return; }
      if (event.target.closest('#finalize-session')) { await save(state.client.from('m_attendance_sessions').update({ finalized: true, finalized_at: new Date().toISOString() }).eq('id', state.sessionId), 'Register finalized.'); await loadPage(); return; }
      const status = event.target.closest('[data-status]'); if (status) { const participantId = status.closest('[data-attendee]').dataset.attendee; await save(state.client.from('m_attendance_records').upsert({ session_id: state.sessionId, participant_id: participantId, status: status.dataset.status, marked_by: state.session.user.id, marked_at: new Date().toISOString() }, { onConflict: 'session_id,participant_id' }), 'Attendance updated.'); await loadPage(); return; }
      const moduleButton = event.target.closest('[data-open-module]'); if (moduleButton) { state.moduleId = moduleButton.dataset.openModule; await loadPage(); return; }
      if (event.target.closest('#back-modules')) { state.moduleId = null; await loadPage(); return; }
      const studied = event.target.closest('[data-studied]'); if (studied) { if (!state.participantId) throw new Error('Participant profile not found.'); await save(state.client.from('m_resource_progress').upsert({ participant_id: state.participantId, resource_id: studied.dataset.studied }, { onConflict: 'participant_id,resource_id' }), 'Learning item marked as studied.'); await loadPage(); return; }
      const submission = event.target.closest('[data-open-submission]'); if (submission) { state.submissionId = submission.dataset.openSubmission; await loadPage(); return; }
      if (event.target.closest('#back-grading')) { state.submissionId = null; await loadPage(); }
    } catch (error) { console.error(error); const form = event.target.closest('form'); if (!setFormError(form, error.message || 'Action failed.')) toast(error.message || 'Action failed.'); }
  });

  document.addEventListener('change', event => {
    if (event.target.name === 'kind' && event.target.closest('#content-modal-form')) { const reading = event.target.value === 'reading'; document.querySelector('[data-content-text]').hidden = !reading; document.querySelector('[data-content-url]').hidden = reading; }
    if (event.target.id === 'question-type') { const automatic = ['multiple_choice', 'checkboxes'].includes(event.target.value); document.querySelector('[data-auto-question]').hidden = !automatic; document.querySelector('[data-manual-question]').hidden = automatic; }
  });

  document.addEventListener('submit', async event => {
    event.preventDefault(); const form = event.target; const data = Object.fromEntries(new FormData(form).entries()); const button = form.querySelector('[type=submit]'); setFormError(form, ''); if ($('login-message')) { $('login-message').textContent = ''; $('login-message').className = 'login-message'; } if (button) button.disabled = true;
    try {
      if (form.id === 'password-login') { const { error } = await state.client.auth.signInWithPassword({ email: data.email, password: data.password }); if (error) throw error; return; }
      if (form.id === 'magic-login') { const { error } = await state.client.auth.signInWithOtp({ email: data.email, options: { emailRedirectTo: location.origin } }); if (error) throw error; $('login-message').textContent = 'Magic link sent. Check your email.'; $('login-message').className = 'login-message success'; return; }
      if (form.id === 'participant-signup') {
        if (data.password !== data.confirm_password) throw new Error('The passwords do not match.'); const normalizedCode = String(data.signup_code).trim().toUpperCase();
        const { data: valid, error: validationError } = await state.client.rpc('m_validate_signup_code', { raw_code: normalizedCode }); if (validationError) throw validationError; if (!valid?.length) throw new Error('This cohort code is invalid, expired or has reached its signup limit.');
        const { data: authData, error } = await state.client.auth.signUp({ email: data.email, password: data.password, options: { data: { signup_code: normalizedCode, display_name: data.display_name.trim(), business_name: data.business_name?.trim() || '', state: data.state?.trim() || '' } } }); if (error) throw error;
        if (!authData.session) { state.authMode = 'signin'; renderLogin(`Account created for ${valid[0].cohort_name}. Check your email to confirm it, then sign in.`, 'success'); } return;
      }
      if (form.id === 'programme-modal-form') await save(state.client.from('m_programmes').insert({ name: data.name, description: data.description || null }), 'Programme created.');
      else if (form.id === 'cohort-modal-form') await save(state.client.from('m_cohorts').insert({ programme_id: data.programme_id, name: data.name, state: data.state || null, starts_on: data.starts_on || null, ends_on: data.ends_on || null }), 'Cohort created.');
      else if (form.id === 'signup-code-modal-form') { const validUntil = data.valid_until ? new Date(data.valid_until).toISOString() : null; const { data: result, error } = await state.client.rpc('m_create_signup_code', { target_cohort: data.cohort_id, valid_until: validUntil, allowed_uses: Number(data.allowed_uses) }); if (error) throw error; state.generatedCode = result?.[0]; if (!state.generatedCode) throw new Error('The signup code could not be generated.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'cohort-access-modal-form') await save(state.client.from('m_cohort_access').upsert({ user_id: data.user_id, cohort_id: data.cohort_id }, { onConflict: 'user_id,cohort_id' }), 'Cohort access granted.');
      else if (form.id === 'assign-modal-form') { await save(state.client.from('m_course_assignments').upsert({ participant_id: data.participant_id, course_id: data.course_id, assigned_by: state.session.user.id }, { onConflict: 'participant_id,course_id' }), 'Course assigned. Current and future modules are now available to this participant.'); }
      else if (form.id === 'course-modal-form') { const { data: created, error } = await state.client.from('m_courses').insert({ title: data.title, description: data.description || null, created_by: state.session.user.id }).select('id').single(); if (error) throw error; state.courseId = created.id; toast('Course workspace created.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'module-modal-form') await save(state.client.from('m_modules').insert({ course_id: data.course_id, title: data.title, description: data.description || null, sequence_number: Number(data.sequence_number), pass_mark: Number(data.pass_mark), published: data.published === 'true', created_by: state.session.user.id }), 'Module added.');
      else if (form.id === 'content-modal-form') { const kind = new FormData(form).get('kind'); if (kind === 'reading' && !data.content?.trim()) throw new Error('Add the reading text before saving.'); if (kind !== 'reading' && !data.external_url?.trim()) throw new Error(`Add the ${typeLabels[kind].toLowerCase()} URL before saving.`); await save(state.client.from('m_module_resources').insert({ module_id: data.module_id, title: data.title, kind, content: kind === 'reading' ? data.content.trim() : null, external_url: kind === 'reading' ? null : data.external_url.trim(), sequence_number: Number(data.sequence_number), required: new FormData(form).has('required') }), 'Learning item added.'); }
      else if (form.id === 'assessment-modal-form') { const { data: created, error } = await state.client.from('m_assessments').insert({ module_id: data.module_id, title: data.title, description: data.description || null, pass_mark: Number(data.pass_mark), grading_mode: data.grading_mode, created_by: state.session.user.id }).select('id').single(); if (error) throw error; state.assessmentId = created.id; toast('Assessment created. Add the first question.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'question-modal-form') {
        const automatic = ['multiple_choice', 'checkboxes'].includes(data.question_type); let options = null; let correctAnswer = null;
        if (automatic) { options = String(data.options || '').split(/\r?\n/).map(v => v.trim()).filter(Boolean); if (options.length < 2) throw new Error('Add at least two answer choices.'); const numbers = String(data.correct_options || '').split(',').map(v => Number(v.trim())).filter(Number.isInteger); if (!numbers.length || numbers.some(v => v < 1 || v > options.length)) throw new Error('Enter valid correct choice numbers.'); if (data.question_type === 'multiple_choice' && numbers.length !== 1) throw new Error('Multiple choice requires exactly one correct choice number.'); correctAnswer = data.question_type === 'multiple_choice' ? options[numbers[0] - 1] : [...new Set(numbers)].sort((a, b) => a - b).map(v => options[v - 1]); }
        const { data: question, error } = await state.client.from('m_assessment_questions').insert({ assessment_id: state.assessmentId, prompt: data.prompt, question_type: data.question_type, options, required: new FormData(form).has('required'), points: Number(data.points), sequence_number: Number(data.sequence_number) }).select('id').single(); if (error) throw error;
        if (automatic) { const { error: keyError } = await state.client.from('m_assessment_keys').insert({ question_id: question.id, correct_answer: correctAnswer, explanation: data.explanation || null }); if (keyError) throw keyError; }
        const questionTypes = await rows('m_assessment_questions', 'question_type', q => q.eq('assessment_id', state.assessmentId)); const hasAuto = questionTypes.some(v => ['multiple_choice', 'checkboxes'].includes(v.question_type)); const hasManual = questionTypes.some(v => !['multiple_choice', 'checkboxes'].includes(v.question_type)); await state.client.from('m_assessments').update({ grading_mode: hasAuto && hasManual ? 'mixed' : hasManual ? 'mentor' : 'automatic' }).eq('id', state.assessmentId);
        toast('Question added.'); form.closest('dialog')?.close(); await loadPage(); return;
      }
      else if (form.id === 'session-modal-form') await save(state.client.from('m_attendance_sessions').insert({ cohort_id: data.cohort_id, meeting_number: Number(data.meeting_number), session_date: data.session_date, starts_at: data.starts_at || null, title: data.title, delivery_mode: data.delivery_mode, join_url: data.join_url || null, location: data.location || null, created_by: state.session.user.id }), 'Class register created.');
      else if (form.classList.contains('note-form')) { if (!state.participantId) throw new Error('Participant profile not found.'); await save(state.client.from('m_private_notes').upsert({ participant_id: state.participantId, resource_id: form.dataset.resource, note: data.note || '', updated_at: new Date().toISOString() }, { onConflict: 'participant_id,resource_id' }), 'Private notes saved.'); return; }
      else if (form.id === 'assessment-submit-form') { const formData = new FormData(form); const answers = {}; form.querySelectorAll('[data-question-id]').forEach(fieldset => { const id = fieldset.dataset.questionId; const type = fieldset.dataset.questionType; const name = `q_${id}`; answers[id] = type === 'checkboxes' ? formData.getAll(name) : formData.get(name); }); const { data: result, error } = await state.client.rpc('m_submit_assessment', { target_assessment: form.dataset.assessment, submitted_answers: answers }); if (error) throw error; toast(result.status === 'submitted' ? 'Assignment submitted to your mentor.' : `Assessment graded: ${result.final_score}%.`); await loadPage(); return; }
      else if (form.id === 'grade-submission-form') { const { data: result, error } = await state.client.rpc('m_grade_submission', { target_submission: form.dataset.submission, grade_score: Number(data.grade_score), grade_feedback: data.grade_feedback }); if (error) throw error; toast(`Grade published: ${result.final_score}%.`); await loadPage(); return; }
      else return;
      form.closest('dialog')?.close(); await loadPage();
    } catch (error) {
      console.error(error); const message = error.message || 'Action failed.';
      if (!setFormError(form, message)) { const login = $('login-message'); if (login && ['password-login', 'magic-login', 'participant-signup'].includes(form.id)) { login.textContent = message; login.className = 'login-message error'; } else toast(message); }
    } finally { if (button) button.disabled = false; }
  });

  async function start() {
    const cfg = window.PORTAL_CONFIG || {}; if (!cfg.supabaseUrl || !cfg.supabasePublishableKey) throw new Error('Supabase configuration missing.');
    state.client = window.supabase.createClient(cfg.supabaseUrl, cfg.supabasePublishableKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } });
    const { data, error } = await state.client.auth.getSession(); if (error) return renderLogin(error.message, 'error'); state.session = data.session; if (!state.session) renderLogin(); else await loadMembership();
    state.client.auth.onAuthStateChange(async (event, session) => { if (['SIGNED_IN', 'SIGNED_OUT', 'USER_UPDATED'].includes(event)) { state.session = session; state.member = null; state.participantId = null; resetDetails(); if (!session) renderLogin(); else setTimeout(() => loadMembership().catch(error => renderLogin(error.message, 'error')), 0); } });
  }
  start().catch(error => { console.error(error); $('content').innerHTML = `<section class="card setup-card"><h1>Portal could not start</h1><p>${esc(error.message)}</p></section>`; });
})();
